export async function createScene(engine, canvas, BABYLON) {
  console.clear();
  const scene = new BABYLON.Scene(engine);
  scene.clearColor = BABYLON.Color4.FromHexString("#312728FF");
  scene.useRightHandedSystem = true;

  var camera = new BABYLON.ArcRotateCamera("camera", BABYLON.Tools.ToRadians(90), BABYLON.Tools.ToRadians(65), 10, BABYLON.Vector3.Zero(), scene);
  camera.setTarget(new BABYLON.Vector3(-5.37, 1.14, -3.54));
  camera.alpha = 1.82;
  camera.beta = 1.48;
  camera.radius = 301;
  camera.inertia = 0.4;
  camera.wheelDeltaPercentage = 0.3;
  camera.panningSensibility = 10000;
  camera.minZ = 0.01;
  camera.maxZ = 10000;
  camera.attachControl(canvas, true);

  var light = new BABYLON.HemisphericLight("light", new BABYLON.Vector3(0, -0.09, -1), scene);

  const hdrTexture = BABYLON.CubeTexture.CreateFromPrefilteredData("https://assets.babylonjs.com/textures/environment.env", scene);
  scene.environmentTexture = hdrTexture;

  var fontData = await (await fetch("https://assets.babylonjs.com/fonts/Kenney Future Regular.json")).json();

  const letterCount = 10;
  const step = 1 / letterCount;

  function createTextMesh(text) {
    var textMesh = BABYLON.MeshBuilder.CreateText(text, text, fontData, {
      size: 16,
      resolution: 64,
      depth: 10,
      perLetterFaceUV: (index) => {
        const startX = index * step;
        return [new BABYLON.Vector4(0, 0, 1, 1), new BABYLON.Vector4(startX, 0, startX + step, 1), new BABYLON.Vector4(startX, 0, startX + step, 1)];
      },
    });

    return textMesh;
  }

  function createGradientMat(name, colors) {
    const gradientMaterial = new BABYLON.PBRMaterial(name, scene);
    const gradientTexture = new BABYLON.DynamicTexture("gradientTex" + name, { width: 512, height: 128 }, scene, true);
    const ctx = gradientTexture.getContext();

    const gradient = ctx.createLinearGradient(0, 0, 512, 0);
    for (let i = 0; i < colors.length; i++) {
      gradient.addColorStop(i / colors.length, colors[i].startsWith("#") ? colors[i] : "#" + colors[i]);
    }

    ctx.fillStyle = gradient;
    ctx.fillRect(0, 0, 512, 128);
    gradientTexture.update();

    gradientMaterial.albedoTexture = gradientTexture;
    gradientMaterial.backFaceCulling = false;
    gradientMaterial.metallic = 0.2;
    gradientMaterial.roughness = 0.05;
    gradientMaterial.specularIntensity = 1.15;

    gradientMaterial.reflectionTexture = hdrTexture;
    gradientMaterial.environmentIntensity = 1.2;

    return gradientMaterial;
  }

  let colors_pink = ["#fbc4ab", "#f8ad9d", "#f4978e", "#f08080"];
  let colors_brown = ["#ff9900", "#ffcc99", "#552200"];
  let colors_green = ["02c39a", "00a896", "028090", "05668d"];
  let colors_skyblue = ["ffd6ff", "e7c6ff", "c8b6ff", "b8c0ff", "bbd0ff"];
  let colors_yellow = ["ffc971", "ffb627", "ff9505", "e2711d", "cc5803"];
  let colors_mixed = ["f79256", "fbd1a2", "7dcfb6", "00b2ca", "1d4e89"];
  let colors_red = ["e4b1ab", "e39695", "f26a8d", "ef233c", "d80032"];
  let colors_purple = ["ea698b", "d55d92", "c05299", "ac46a1", "973aa8", "822faf", "6d23b6", "6411ad", "571089", "47126b"];
  let colors_blue = ["a2d6f9", "49b6ff", "1e96fc", "072ac8"];
  let colors_green2 = ["aad576", "73a942", "538d22", "245501", "1a4301", "143601"];

  var myText = createTextMesh("GRADIENT");
  myText.position.y = 60;
  var myText2 = createTextMesh("GRADIENT");
  myText2.position.y = 40;
  var myText3 = createTextMesh("GRADIENT");
  myText3.position.y = 20;
  var myText4 = createTextMesh("GRADIENT");
  myText4.position.y = 0;
  var myText5 = createTextMesh("GRADIENT");
  myText5.position.y = -20;
  var myText6 = createTextMesh("GRADIENT");
  myText6.position.y = -40;
  var myText7 = createTextMesh("GRADIENT");
  myText7.position.y = -60;
  var myText8 = createTextMesh("GRADIENT");
  myText8.position.y = -80;
  var myText9 = createTextMesh("GRADIENT");
  myText9.position.y = -100;
  var myText10 = createTextMesh("GRADIENT");
  myText10.position.y = 80;

  const gradientMat = createGradientMat("pink", colors_pink);
  myText.material = gradientMat;
  const gradientMat2 = createGradientMat("brown", colors_brown);
  myText2.material = gradientMat2;
  const gradientMat3 = createGradientMat("green", colors_green);
  myText3.material = gradientMat3;
  const gradientMat4 = createGradientMat("skyblye", colors_skyblue);
  myText4.material = gradientMat4;
  const gradientMat5 = createGradientMat("yellow", colors_yellow);
  myText5.material = gradientMat5;
  const gradientMat6 = createGradientMat("mixed", colors_mixed);
  myText6.material = gradientMat6;
  const gradientMat7 = createGradientMat("red", colors_red);
  myText7.material = gradientMat7;
  const gradientMat8 = createGradientMat("purple", colors_purple);
  myText8.material = gradientMat8;
  const gradientMat9 = createGradientMat("blue", colors_blue);
  myText9.material = gradientMat9;
  const gradientMat10 = createGradientMat("green2", colors_green2);
  myText10.material = gradientMat10;

  return scene;
}
